      attrs: ['data-state', 'hidden', 'open', 'popover', 'data-anchored', 'data-placement'],
      classes: ['ds-dialog--closing', 'ds-sheet--closing', 'ds-dialog--nested', 'ds-dialog--hidden', 'ds-sheet--hidden'],
